namespace crtbench {
struct Scope;
extern thread_local double times[24];
extern thread_local uint64_t calls[24];
extern thread_local Scope* top;
inline double now(){return std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now().time_since_epoch()).count();}
struct Scope {
 int id; double start,children=0; Scope* parent;
 Scope(int i):id(i),start(now()),parent(top){top=this;}
 void finish(){double elapsed=now()-start;times[id]+=elapsed-children;calls[id]++;if(parent)parent->children+=elapsed;}
 void next(int i){finish();id=i;start=now();children=0;}
 ~Scope(){finish();top=parent;}
};
}
#define CPROF(i) crtbench::Scope _cprof(i)
#define CNEXT(i) _cprof.next(i)
