namespace crt {

class ColorAttr: public GenericAttr<uchar> {
public:
	int qc[4];
	int out_components = 4;      //number of output components (either 3 or 4).
	ColorAttr(int components = 4): GenericAttr<uchar>(components) {
		qc[0] = qc[1] = qc[2] = 4;
		qc[3] = 8;
	}
	virtual int codec() { return COLOR_CODEC; }

	void setQ(int r_bits, int g_bits, int b_bits, int a_bits) {
		qc[0] = 1<<(8 - r_bits);
		qc[1] = 1<<(8 - g_bits);
		qc[2] = 1<<(8 - b_bits);
		qc[3] = 1<<(8 - a_bits);
	}

	virtual void quantize(uint32_t nvert, const char *buffer);
	virtual void dequantize(uint32_t nvert);

	virtual void encode(uint32_t nvert, OutStream &stream) {
		stream.restart();
		for(int c = 0; c < N; c++)
			stream.write<uchar>((uchar)qc[c]);

		stream.encodeValues<char>(nvert, (char *)diffs.data(), N);
		size = stream.elapsed();
	}
	virtual void decode(uint32_t /*nvert*/, InStream &stream) {
		for(int c = 0; c < N; c++)
			qc[c] = stream.readUint8();
		stream.decodeValues<uchar>((uchar *)buffer, N);
	}
};

} //namespace

#endif // CRT_COLOR_ATTRIBUTE_H

using namespace crt;


void ColorAttr::quantize(uint32_t nvert, const char *buffer) {
	uint32_t n = N*nvert;

	values.resize(n);
	diffs.resize(n);
	switch(format) {
	case UINT8:
	{
		const uint8_t *c = (const uint8_t *)buffer;
		uint8_t *v = values.data();
		Color4b y;
		for(uint32_t i = 0; i < nvert; i++) {
			for(int k = 0; k < N; k++)
				y[k] = c[k]/qc[k];
			y = y.toYCC();
			for(int k = 0; k < N; k++)
				v[k] = y[k];
			c += N;
			v += N;
		}
	}
		break;

	case FLOAT:
	{
		Color4b y;
		y[3] = 255;
		const float *c = (const float *)buffer;
		uint8_t *v = values.data();
		for(uint32_t i = 0; i < nvert; i++) {
			for(int k = 0; k < N; k++)
				y[k] = ((int)(c[k]*255.0f))/qc[k];
			y = y.toYCC();
			for(int k = 0; k < N; k++)
				v[k] = y[k];
			c += N;
			v += N;
		}
	}
		break;
#ifndef NO_EXCEPTIONS
	default: throw "Unsupported color input format.";
#else
	default: break;
#endif
	}
	bits = 0;
}

void ColorAttr::dequantize(uint32_t nvert) {
	if(!buffer) return;

	switch(format) {
	case UINT8:
	{
		//this is inplace decoding! goiong from 3 to 4 require going in reverse.
		uint8_t *c = ((uint8_t *)buffer) + N*nvert;
		uint8_t *target = ((uint8_t *)buffer) + out_components*nvert;
		Color4b color;
		color[3] = 255;

		while(c > (uint8_t *)buffer) {
			c -= N;
			target -= out_components;

			for(int k = 0; k < N; k++)
				color[k] = c[k];
			color = color.toRGB();
			for(int k = 0; k < out_components; k++)
				target[k] = color[k]*qc[k];
		}
		break;
	}
	case FLOAT:
	{
		std::vector<Color4b> colors(nvert);
		memcpy(colors.data(), buffer, nvert*sizeof(Color4b));
		float *c = (float *)buffer;

		for(uint32_t i = 0; i < nvert; i++) {
			Color4b &rgb = colors[i];
			rgb = rgb.toRGB();
			for(int k = 0; k < out_components; k++)
				c[k] = (c[k]*qc[k])/255.0f;
			c += out_components;
		}
		break;
	}
#ifndef NO_EXCEPTIONS
	default: throw "Unsupported color output format.";
#else
	default: break;
#endif

	}
}


