#include <vector>
#include <algorithm>
#include <cstdint>
struct CornerBuildEdge {uint32_t other,corner;};
#ifdef CORTO_CORNER_SCRATCH
struct CornerScratch {
 std::vector<uint32_t> opposite,count;
 std::vector<CornerBuildEdge> edges;
};
inline CornerScratch& cornerScratch(){static thread_local CornerScratch s;return s;}
#endif
class CornerFaces {
public:
 const uint32_t* vertices;size_t count;uint32_t referenced=0,paired=0;
#ifdef CORTO_CORNER_SCRATCH
 std::vector<uint32_t>& opposite;
#else
 std::vector<uint32_t> opposite;
#endif
 struct AdjacentFace {const uint32_t* o;uint32_t operator[](int k)const{return o[k]==~0u?~0u:o[k]/3;}};
 struct AdjacentSide {const uint32_t* o;uint32_t operator[](int k)const{return o[k]==~0u?~0u:o[k]%3;}};
 struct View {const uint32_t* f;AdjacentFace t;AdjacentSide i;};
#ifdef CORTO_CORNER_SCRATCH
 CornerFaces(const uint32_t* v,size_t n):vertices(v),count(n),opposite(cornerScratch().opposite){opposite.resize(n*3);std::fill(opposite.begin(),opposite.end(),~0u);}
#else
 CornerFaces(const uint32_t* v,size_t n):vertices(v),count(n),opposite(n*3,~0u){}
#endif
 size_t size()const{return count;}
 View operator[](size_t i)const{return {vertices+i*3,{opposite.data()+i*3},{opposite.data()+i*3}};}
};
static void buildTopology(CornerFaces& faces,uint32_t nvert){
 CPROF(5);
#ifdef CORTO_CORNER_SCRATCH
 auto& count=cornerScratch().count;count.resize(nvert);std::fill(count.begin(),count.end(),0);
#else
 std::vector<uint32_t> count(nvert,0);
#endif
 const uint32_t* v=faces.vertices;
 if(faces.count*3>=0x80000000ull)throw "corner index limit exceeded";
 for(size_t i=0;i<faces.count;i++){
#ifdef CORTO_MERGE_REFERENCE
  for(int k=0;k<3;k++){uint32_t a=v[i*3+k],b=v[i*3+(k+1)%3];count[std::min(a,b)]++;count[std::max(a,b)]|=0x80000000u;}
#else
  count[std::min(v[i*3],v[i*3+1])]++;count[std::min(v[i*3+1],v[i*3+2])]++;count[std::min(v[i*3+2],v[i*3])]++;
#endif
 }
 CNEXT(6);uint32_t sum=0;for(auto& c:count){
#ifdef CORTO_MERGE_REFERENCE
 faces.referenced+=c!=0;uint32_t n=c&0x7fffffffu;
#else
 uint32_t n=c;
#endif
 c=sum;sum+=n;}
 // Lower vertex is implicit in the bucket. High bit stores edge orientation.
 using Edge=CornerBuildEdge;
 CNEXT(7);
#ifdef CORTO_CORNER_SCRATCH
 auto& edges=cornerScratch().edges;edges.resize(faces.count*3);
#else
 std::vector<Edge> edges(faces.count*3);
#endif
 for(uint32_t i=0;i<faces.count;i++)for(uint32_t k=0;k<3;k++){
  uint32_t a=v[i*3+(k+1)%3],b=v[i*3+(k+2)%3];uint32_t lo=std::min(a,b);
  edges[count[lo]++]={std::max(a,b),(i*3+k)|(a>b?0x80000000u:0u)};
 }
 CNEXT(8);uint32_t begin=0;
 for(uint32_t b=0;b<nvert;b++){uint32_t end=count[b];std::sort(edges.begin()+begin,edges.begin()+end,[](const Edge&a,const Edge&b){return a.other<b.other;});begin=end;}
 CNEXT(9);begin=0;
 for(uint32_t b=0;b<nvert;b++){
  uint32_t end=count[b];Edge previous={~0u,~0u};bool valid=false;
  for(uint32_t j=begin;j<end;j++){
   const Edge e=edges[j];
   if(valid&&e.other==previous.other&&((e.corner^previous.corner)&0x80000000u)){
    uint32_t c=e.corner&0x7fffffffu,p=previous.corner&0x7fffffffu;
    if(faces.opposite[c]==~0u&&faces.opposite[p]==~0u){faces.opposite[c]=p;faces.opposite[p]=c;faces.paired++;}
   }else{previous=e;valid=true;}
  }
  begin=end;
 }
}

#endif
