  std::vector<uint32_t> face_ids(nf);std::vector<uint8_t> seen_face;
  if constexpr(RestoreFaceIds){seen_face.assign(nf,0);const unsigned char* fp=face_stream;const unsigned char* fend=face_stream+face_size;uint32_t previous=0;for(uint32_t i=0;i<nf;i++){uint32_t value;if(!exact_ids::unvarint(fp,fend,value))return 3;int64_t id=int64_t(previous)+exact_ids::unzz(value);if(id<0||id>=nf||seen_face[id]++)return 3;face_ids[i]=previous=uint32_t(id);}if(fp!=fend)return 3;}
